// Verify the native render clock in a copied null-audio project, including
// background windows whose playhead animation is intentionally suspended.
(() => {
 if(location.hostname!=='127.0.0.1'||window.__cicadaObservationClockSmoke)return;window.__cicadaObservationClockSmoke=true;
 const read=async name=>{const r=await fetch('/api/'+name,{cache:'no-store'});if(!r.ok)throw new Error(name+': '+r.status);return r.json()};
 const wait=async(check,label)=>{const end=performance.now()+30000;while(performance.now()<end){if(await check())return;await new Promise(r=>setTimeout(r,50))}throw new Error('Timed out: '+label)};
 const click=(label,scope=document)=>{const button=[...scope.querySelectorAll('button')].find(n=>n.textContent.trim()===label&&!n.disabled);if(!button)throw new Error('Missing '+label);button.click()};
 const stamp=value=>{const bytes=Uint8Array.from(atob(value.frames.transport),c=>c.charCodeAt(0));if(bytes.length!==64||bytes[0]!==1)throw new Error('Transport ABI changed');return new DataView(bytes.buffer).getBigInt64(14,true).toString()};
 (async()=>{
  await wait(()=>window.__gosx?.ready&&document.querySelector('#studio-shell[data-shell-actions=ready]'),'managed UI');const source=(await read('state')).source,audio=await read('audio/config');if(!source.includes('cicada-print-sources-test: disposable fixture')||audio.options.inputEnabled||String(audio.inventory.backendName||audio.inventory.backend).toLowerCase()!=='null')throw new Error('Use copied synthetic takes and null audio');
  click('Play full song',document.querySelector('#arrangement'));await wait(async()=>{const s=await read('transport');return s.playing&&s.frameAgeNanos>=0&&s.frameAgeNanos<1e9},'native render clock');const checks=['native render age is available without synchronizing browser wall clocks'];
  click('Pause',document.querySelector('[role=toolbar][aria-label=Transport]'));await wait(async()=>!(await read('transport')).playing,'paused');const first=await read('transport'),originalStamp=stamp(first);await new Promise(r=>setTimeout(r,250));const second=await read('transport');if(stamp(second)!==originalStamp||second.frameAgeNanos<first.frameAgeNanos+150e6)throw new Error('Repeated publication refreshed an old render clock');checks.push('paused native telemetry retains its original render timestamp while its reported age increases');
  click('Play',document.querySelector('[role=toolbar][aria-label=Transport]'));await wait(async()=>{const s=await read('transport');return s.playing&&stamp(s)!==originalStamp&&s.frameAgeNanos>=0&&s.frameAgeNanos<1e9},'fresh clock resumed');click('Stop listening',document.querySelector('#arrangement'));await wait(async()=>!(await read('transport')).playing,'stopped');if((await read('state')).source!==source)throw new Error('Clock test rewrote source');checks.push('resuming produces new observations without changing the score');checks.push('native document visibility: '+document.visibilityState);return {type:'cicada-native-smoke',ok:true,checks};
 })().catch(error=>({type:'cicada-native-smoke',ok:false,checks:[],error:String(error)+'\n'+String(error.stack||'')+'\n'+document.body.innerText.slice(-1000)})).then(result=>window.chrome?.webview?.postMessage(JSON.stringify(result)));
})();
